package vn.codegym.inotes;import java.sql.*;import java.util.*;public class NoteDBStrategy implements NoteStrategy{private Connection open()throws SQLException{return DriverManager.getConnection("jdbc:mysql://localhost:3306/inotes_db","root","password");}public void save(Note n)throws Exception{String sql=n.id()==0?"INSERT INTO notes(title,content,type_id) VALUES(?,?,?)":"UPDATE notes SET title=?,content=?,type_id=? WHERE id=?";try(Connection c=open();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,n.title());p.setString(2,n.content());p.setInt(3,n.typeId());if(n.id()!=0)p.setInt(4,n.id());p.executeUpdate();}}public void delete(int id)throws Exception{try(Connection c=open();PreparedStatement p=c.prepareStatement("DELETE FROM notes WHERE id=?")){p.setInt(1,id);p.executeUpdate();}}private List<Note> query(String sql,String value)throws Exception{List<Note> list=new ArrayList<>();try(Connection c=open();PreparedStatement p=c.prepareStatement(sql)){if(value!=null){p.setString(1,"%"+value+"%");p.setString(2,"%"+value+"%");}try(ResultSet r=p.executeQuery()){while(r.next())list.add(new Note(r.getInt(1),r.getString(2),r.getString(3),r.getInt(4)));}}return list;}public List<Note> findAll()throws Exception{return query("SELECT id,title,content,type_id FROM notes",null);}public List<Note> search(String k)throws Exception{return query("SELECT id,title,content,type_id FROM notes WHERE title LIKE ? OR content LIKE ?",k);}}
